  const drawers = { biography: { portrait: true, title: 'Biographical note', body: 'Favour Akintoye is a Nigerian product builder, founder and independent analyst studying the space between technology, institutions and implementation.', items: ['Computer Engineering student, Federal University of Technology, Akure', 'Based in Nigeria', 'Works across product, technology, strategy, growth and research'] }, practice: { title: 'Disciplines & practice', body: 'A cross-disciplinary practice built around moving from problem definition to functioning systems, then examining what happened.', items: ['Product discovery and product management', 'Technical product construction and system design', 'Growth, go-to-market and distribution', 'Independent company and market research'] }, experience: { title: 'Selected experience', body: 'Selected work across founder-led product development, product management, growth advisory and technical delivery.', items: ['Founder: Payla', 'Product Manager / PLG Advisor: MyLurah', 'Product Manager, Growth & GTM: Aortem', 'Independent research: Startup Reality Check', 'Product and technical work: NexaHealth', 'Technical product management: Layla Orders'] }, observations: { title: 'Observations & questions', body: 'The archive is selective. These are working principles rather than claims of finality.', items: ['Evidence before thesis. Separate fact, inference and argument.', 'A product is not validated by its existence; it is validated by behaviour and use.', 'Distribution is part of the product system, not a final marketing layer.', 'As systems scale, the binding constraint migrates.'] } };
  $$('.cabinet-door').forEach(b => b.addEventListener('click', () => { const d = drawers[b.dataset.drawer]; $$('.cabinet-door').forEach(x => x.classList.toggle('active', x === b)); const txt = `<span class="small-label">${d.title.toUpperCase()} / EXAMINATION</span><p>${d.body}</p><ul>${d.items.map(x => `<li>${x}</li>`).join('')}</ul>`; $('#drawerContent').innerHTML = d.portrait ? `<div class="drawer-bio"><figure class="drawer-portrait"><picture><source type="image/webp" srcset="assets/images/portrait-480.webp 480w, assets/images/portrait-960.webp 960w" sizes="(max-width:620px) 70vw, 260px"><img src="assets/images/portrait-960.jpg" width="960" height="1200" alt="Portrait of Favour Akintoye in round gold-rimmed glasses and a denim shirt" decoding="async"></picture><figcaption>FIG. 05 / AUTHOR'S RECORD</figcaption></figure><div>${txt}</div></div>` : txt }));
  const records = { payla: { label: 'PL.001 / PRODUCT CONSTRUCTION', title: 'Payla: payment identity', body: '<p><b>Problem.</b> Freelancers and small businesses often send payment details manually, leaving payers to interpret account information and confirm the recipient.</p><p><b>Intervention.</b> A shareable payment identity and Paylink experience that presents the recipient identity before transfer, with payment tracking and related business tools.</p><p><b>My contribution.</b> Founder, product design and backend implementation. Built with FastAPI, Firebase/Firestore and Paystack integration.</p><p><b>Evidence boundary.</b> Earlier reported snapshot: 50+ registered and configured users, 15 users who had received payments. These are historical user-reported figures, not current live analytics.</p><p><b>Examination.</b> Product architecture, onboarding, transaction confirmation, monetisation and distribution experiments.</p><a href="https://payla.ng/@favour" target="_blank" rel="noreferrer">VISIT PAYLA ↗</a>' }, nexahealth: { label: 'PL.002 / TRUST INFRASTRUCTURE', title: 'NexaHealth: medicine verification', body: '<p><b>Problem.</b> Consumers face uncertainty about medicine authenticity and where to obtain reliable products.</p><p><b>System.</b> Medicine verification, counterfeit-drug reporting and pharmacy discovery, organised around trust at the point of purchase.</p><p><b>Technology.</b> FastAPI, Firebase and Google Cloud Vision.</p><p><b>My contribution.</b> Product and technical contribution. Do not interpret the reported platform metrics as solely attributable to one individual.</p><p><b>Evidence boundary.</b> Project-reported figures have included 2,000+ registered users and 101 daily active users; the measurement period and DAU methodology should accompany any public use.</p>' }, layla: { label: 'PL.003 / CONVERSATIONAL SYSTEM', title: 'Layla Orders: order assurance', body: '<p><b>Problem.</b> A catering business needed a reliable path from a WhatsApp order to verified payment and clear order status.</p><p><b>System.</b> A conversational ordering assistant that checks Paystack transaction references, records order state and routes exceptions to a human operator.</p><p><b>My contribution.</b> Technical product management and workflow design. Built as a take-home product exercise using Chord and Paystack test mode.</p><p><b>Important distinction.</b> This was a test-mode prototype, not a claim of a production deployment.</p>' }, mylurah: { label: '03.01 / PRODUCT & PLG', title: 'MyLurah: product and engagement', body: '<p>Product Manager and product-led growth advisor for a culturally grounded women’s health platform. Work included product strategy, cross-functional alignment, engagement initiatives and growth/partnership thinking.</p><p>Impact should be described as contribution to initiatives associated with user growth, not as sole ownership of all acquisition or engagement outcomes.</p>' }, aortem: { label: '03.02 / GROWTH & GTM', title: 'Aortem: outbound operations', body: '<p>Independently executed 94 outbound campaigns reaching 5,900+ prospects, with a reported 29.6% average email open rate. Also contributed to product roadmap and go-to-market work.</p><p>These are campaign activity and performance figures, not revenue or conversion claims.</p>' }, blocade: { label: '03.03 / DISTRIBUTION', title: 'Blocade: content distribution', body: '<p>Content and distribution work associated with 675,512 Instagram views in 14 days. The reach figure describes campaign performance; the specific intervention and attribution should be documented before making stronger causal claims.</p>' } };
